{
            if (campaign == null)
                throw new ArgumentNullException(nameof(campaign));
            if (!campaign.QuestionId.HasValue && campaign.Question == null)
                throw new ArgumentException(nameof(campaign));
            if (campaign.GatherLeads &&
              campaign.AskLeadEmail.HasValue && !campaign.AskLeadEmail.Value &&
              campaign.AskLeadPhone.HasValue && !campaign.AskLeadPhone.Value)
                throw new SaveEntityException("Phone or email field must be selected for lead form if campaign marked to gather leads.");
            if (campaign.GatherLeads && campaign.Question.Answers.All(x => !x.GatherLeads.HasValue || !x.GatherLeads.Value))
                throw new SaveEntityException("At least one answer must selected to gather leads if campaign marked to gather leads.");
            if (campaign.GatherLeads && campaign.SendLeadsToEmail.HasValue && campaign.SendLeadsToEmail.Value && string.IsNullOrWhiteSpace(campaign.LeadsReceiverEmails))
                throw new SaveEntityException("Leads receiver field is required.");

            using (AskapediaDBContext db = new AskapediaDBContext())
            {
                AskCampaign dbCampaign = campaign.ToEntity();
                SaveQuestionAndAnswers(campaign, db, dbCampaign);

                if (campaign.IsNew)
                {
                    dbCampaign.Question = null;
                    db.Campaigns.Add(dbCampaign);
                }
                else
                {
                    var currentCampaign = db.Campaigns.Include(x => x.Question).Include(x => x.Question.Answers).FirstOrDefault(x => x.Id == campaign.Id);
                    db.Entry(currentCampaign).CurrentValues.SetValues(dbCampaign);
                }
                if (!campaign.IsNew)
                {
                    var existingAnswers = db.Answers.Where(x => x.Question.Id == campaign.QuestionId).ToList();
                    foreach (var answer in existingAnswers)
                    {
                        var forRemove = campaign.Question.Answers.Find(x => !x.IsNew && answer.Id == x.Id);
                        if (forRemove == null)
                            db.Answers.Remove(answer);
                    }
                }

                db.SaveChanges();
                return dbCampaign.Id;
            }
        }

